"use client";

import "./sidebar.css";
import { PanelLeft } from "lucide-react";
import React, { useState } from "react";
import { cn } from "@/lib/cn";

import { SidebarContext, useSidebar } from "./sidebar.context";
import { sidebarVariants, type SidebarVariants } from "./sidebar.variants";

export type SidebarProviderProps = {
  defaultOpen?: boolean;
  open?: boolean;
  onOpenChange?: (open: boolean) => void;
  children?: React.ReactNode;
  className?: string;
} & React.ComponentProps<"div">;

export const SidebarProvider = ({
  children,
  className,
  defaultOpen = true,
  open: openProp,
  onOpenChange,
  ...props
}: SidebarProviderProps) => {
  const [internalOpen, setInternalOpen] = useState(defaultOpen);
  const open = openProp ?? internalOpen;

  const setOpen = React.useCallback(
    (value: boolean | ((prev: boolean) => boolean)) => {
      const nextOpen = typeof value === "function" ? value(open) : value;
      if (onOpenChange) {
        onOpenChange(nextOpen);
      } else {
        setInternalOpen(nextOpen);
      }
    },
    [open, onOpenChange]
  );

  const toggleSidebar = React.useCallback(() => {
    setOpen((prev) => !prev);
  }, [setOpen]);

  const slots = sidebarVariants();

  return (
    <SidebarContext.Provider value={{ slots, open, setOpen, toggleSidebar }}>
      <div className={cn(slots.provider(), className)} {...props}>
        {children}
      </div>
    </SidebarContext.Provider>
  );
};

export type SidebarProps = SidebarVariants & React.ComponentProps<"aside">;

export const SidebarRoot = ({ className, children, ...props }: SidebarProps) => {
  const { slots, open } = useSidebar();
  return (
    <aside
      data-collapsed={!open}
      className={cn(slots.root(), className)}
      {...props}
    >
      {children}
    </aside>
  );
};

export type SidebarHeaderProps = React.ComponentProps<"div">;
export const SidebarHeader = ({ className, ...props }: SidebarHeaderProps) => {
  const { slots } = useSidebar();
  return <div className={cn(slots.header(), className)} {...props} />;
};

export type SidebarContentProps = React.ComponentProps<"div">;
export const SidebarContent = ({ className, ...props }: SidebarContentProps) => {
  const { slots } = useSidebar();
  return <div className={cn(slots.content(), className)} {...props} />;
};

export type SidebarFooterProps = React.ComponentProps<"div">;
export const SidebarFooter = ({ className, ...props }: SidebarFooterProps) => {
  const { slots } = useSidebar();
  return <div className={cn(slots.footer(), className)} {...props} />;
};

export type SidebarGroupProps = React.ComponentProps<"div">;
export const SidebarGroup = ({ className, ...props }: SidebarGroupProps) => {
  const { slots } = useSidebar();
  return <div className={cn(slots.group(), className)} {...props} />;
};

export type SidebarGroupLabelProps = React.ComponentProps<"div">;
export const SidebarGroupLabel = ({ className, ...props }: SidebarGroupLabelProps) => {
  const { slots, open } = useSidebar();
  if (!open) return null;
  return <div className={cn(slots.groupLabel(), className)} {...props} />;
};

export type SidebarGroupContentProps = React.ComponentProps<"div">;
export const SidebarGroupContent = ({ className, ...props }: SidebarGroupContentProps) => {
  const { slots } = useSidebar();
  return <div className={cn(slots.groupContent(), className)} {...props} />;
};

export type SidebarMenuProps = React.ComponentProps<"ul">;
export const SidebarMenu = ({ className, ...props }: SidebarMenuProps) => {
  const { slots } = useSidebar();
  return <ul className={cn(slots.menu(), className)} {...props} />;
};

export type SidebarMenuItemProps = React.ComponentProps<"li">;
export const SidebarMenuItem = ({ className, ...props }: SidebarMenuItemProps) => {
  const { slots } = useSidebar();
  return <li className={cn(slots.menuItem(), className)} {...props} />;
};

export type SidebarMenuButtonProps = {
  isActive?: boolean;
} & React.ComponentProps<"button">;

export const SidebarMenuButton = ({
  className,
  isActive,
  children,
  ...props
}: SidebarMenuButtonProps) => {
  const { slots } = useSidebar();
  return (
    <button
      data-active={isActive}
      className={cn(slots.menuButton(), className)}
      {...props}
    >
      {children}
    </button>
  );
};

export type SidebarTriggerProps = React.ComponentProps<"button">;
export const SidebarTrigger = ({ className, children, onClick, ...props }: SidebarTriggerProps) => {
  const { slots, toggleSidebar } = useSidebar();
  return (
    <button
      aria-label="Toggle Sidebar"
      className={cn(slots.trigger(), className)}
      onClick={(e) => {
        onClick?.(e);
        toggleSidebar();
      }}
      {...props}
    >
      {children ?? <PanelLeft />}
    </button>
  );
};

/* eslint-disable perfectionist/sort-objects */

import { tv, type VariantProps } from "tailwind-variants";

export const sidebarVariants = tv({
  slots: {
    provider: "sidebar-provider",
    root: "sidebar",
    header: "sidebar__header",
    content: "sidebar__content",
    footer: "sidebar__footer",
    group: "sidebar__group",
    groupLabel: "sidebar__group-label",
    groupContent: "sidebar__group-content",
    menu: "sidebar__menu",
    menuItem: "sidebar__menu-item",
    menuButton: "sidebar__menu-button",
    trigger: "sidebar__trigger",
  },
  variants: {},
  defaultVariants: {},
});

export type SidebarVariants = VariantProps<typeof sidebarVariants>;

"use client";

import { createContext, useContext } from "react";

import { sidebarVariants } from "./sidebar.variants";

export type SidebarContext = {
  slots: ReturnType<typeof sidebarVariants>;
  open: boolean;
  setOpen: (open: boolean | ((prev: boolean) => boolean)) => void;
  toggleSidebar: () => void;
};

export const SidebarContext = createContext<SidebarContext | null>(null);

export const useSidebar = () => {
  const context = useContext(SidebarContext);
  if (!context) {
    throw new Error("useSidebar must be used within a SidebarProvider");
  }
  return context;
};

.sidebar-provider {
  @apply flex min-h-full w-full text-foreground bg-background;
}

.sidebar {
  @apply flex flex-col h-full w-64 border-r border-border bg-background text-foreground transition-all duration-200 ease-in-out shrink-0 select-none overflow-hidden;
}

.sidebar[data-collapsed="true"] {
  @apply w-16;
}

.sidebar[data-collapsed="true"] .sidebar__header {
  @apply justify-center px-2;
}

.sidebar[data-collapsed="true"] .sidebar__header > *:not(.sidebar__trigger) {
  @apply hidden;
}

.sidebar[data-collapsed="true"] .sidebar__footer {
  @apply justify-center px-2;
}

.sidebar[data-collapsed="true"] .sidebar__footer > *:not(.sidebar__trigger) {
  @apply hidden;
}

.sidebar[data-collapsed="true"] .sidebar__menu-button {
  @apply justify-center px-0 gap-0;
}

.sidebar[data-collapsed="true"] .sidebar__menu-button > span {
  @apply hidden;
}

.sidebar__header {
  @apply flex items-center justify-between p-4 border-b border-border h-14 shrink-0;
}

.sidebar__content {
  @apply flex-1 overflow-y-auto p-2 space-y-4;
}

.sidebar__footer {
  @apply flex items-center justify-between p-4 border-t border-border mt-auto h-14 shrink-0;
}

.sidebar__group {
  @apply flex flex-col gap-1;
}

.sidebar__group-label {
  @apply px-2 text-xs font-semibold text-muted-foreground uppercase tracking-wider;
}

.sidebar__group-content {
  @apply flex flex-col gap-1 mt-1;
}

.sidebar__menu {
  @apply flex flex-col gap-1 list-none p-0 m-0;
}

.sidebar__menu-item {
  @apply list-none;
}

.sidebar__menu-button {
  @apply flex w-full items-center gap-3 rounded-md px-3 py-2 text-sm font-medium text-foreground transition-colors hover:bg-accent hover:text-accent-foreground focus-visible:outline-2 focus-visible:outline-ring disabled:pointer-events-none disabled:opacity-50 cursor-pointer whitespace-nowrap;
}

.sidebar__menu-button[data-active="true"] {
  @apply bg-accent text-accent-foreground font-semibold;
}

.sidebar__trigger {
  @apply inline-flex h-9 w-9 items-center justify-center rounded-md border border-input bg-background text-foreground shadow-xs hover:bg-accent hover:text-accent-foreground transition-colors focus-visible:outline-2 focus-visible:outline-ring cursor-pointer shrink-0;
}

.sidebar__trigger svg {
  @apply h-4 w-4;
}
